SELECT throws_like($Q$SELECT post_transaction('10000000-0000-0000-0000-000000000001','ADJUSTMENT','adj:2',now(),'BACKOFFICE','[{"account_id":"20000000-0000-0000-0000-000000000003","amount":100},{"account_id":"20000000-0000-0000-0000-000000000004","amount":-100}]', NULL, NULL, '90000000-0000-0000-0000-000000000001', NULL)$Q$, $Q$%journal_transaction_check%$Q$, $Q$saisie manuelle sans seconde validation refusée$Q$);
SELECT throws_like($Q$SELECT post_transaction('10000000-0000-0000-0000-000000000001','PURCHASE','dev1:2',now(),'ONLINE','[{"account_id":"20000000-0000-0000-0000-000000000002","amount":50000},{"account_id":"20000000-0000-0000-0000-000000000003","amount":-50000}]')$Q$, $Q$Solde interdit%$Q$, $Q$découvert refusé$Q$);
SELECT throws_like($Q$SELECT post_transaction('10000000-0000-0000-0000-000000000001','PURCHASE','dev1:3',now(),'ONLINE','[{"account_id":"20000000-0000-0000-0000-000000000002","amount":1000},{"account_id":"20000000-0000-0000-0000-000000000003","amount":-900}]')$Q$, $Q$Lignes invalides%$Q$, $Q$lignes déséquilibrées refusées$Q$);
SELECT throws_like($Q$SELECT post_transaction('10000000-0000-0000-0000-000000000001','PAYMENT','dev1:4',now(),'ONLINE','[{"account_id":"20000000-0000-0000-0000-000000000002","amount":100},{"account_id":"20000000-0000-0000-0000-000000000003","amount":-100}]')$Q$, $Q$%journal_transaction_type_check%$Q$, $Q$type de transaction inconnu refusé$Q$);
INSERT INTO account (id, operator_id, ledger_id, code, family, purpose, owner_party_id, normal_side, allow_negative) VALUES
