SELECT lives_ok($Q$SELECT post_transaction('10000000-0000-0000-0000-000000000001','MERCHANT_DEBT_TRANSFER','debt:1',now(),'BATCH','[{"account_id":"20000000-0000-0000-0000-000000000005","amount":100},{"account_id":"20000000-0000-0000-0000-000000000003","amount":-100}]')$Q$, $Q$dette d'un commerçant transférée à l'organisateur$Q$);
SELECT lives_ok($Q$SELECT post_transaction('10000000-0000-0000-0000-000000000001','MERCHANT_DEBT_TRANSFER','debt:2',now(),'BATCH','[{"account_id":"20000000-0000-0000-0000-000000000003","amount":100},{"account_id":"20000000-0000-0000-0000-000000000005","amount":-100}]')$Q$, $Q$contre-écriture de test$Q$);
