SELECT throws_ok($Q$SELECT post_transaction('10000000-0000-0000-0000-000000000001','TOPUP','wave:abc',now(),'PSP_WEBHOOK','[{"account_id":"20000000-0000-0000-0000-000000000001","amount":1},{"account_id":"20000000-0000-0000-0000-000000000002","amount":-1}]')$Q$, 'CL002', NULL, $Q$clé réutilisée : SQLSTATE CL002$Q$);
SELECT throws_ok($Q$SELECT post_transaction('10000000-0000-0000-0000-000000000001','PURCHASE','code:2',now(),'ONLINE','[{"account_id":"20000000-0000-0000-0000-000000000002","amount":10},{"account_id":"20000000-0000-0000-0000-000000000003","amount":-9}]')$Q$, 'CL001', NULL, $Q$lignes invalides : SQLSTATE CL001$Q$);
