SELECT throws_like($Q$INSERT INTO posting (operator_id, ledger_id, transaction_id, line_no, account_id, amount) SELECT operator_id, ledger_id, transaction_id, 99, account_id, 1 FROM posting LIMIT 1$Q$, $Q$%permission denied%$Q$, $Q$rôle applicatif : insertion directe interdite$Q$);
RESET ROLE; SET app.operator_id = '00000000-0000-0000-0000-000000000002';

