CREATE TEMP TABLE hr AS SELECT wallet_topup_headroom('30000000-0000-0000-0000-000000000091', now()) AS h,
  (SELECT -sum(amount) FROM posting WHERE account_id = '20000000-0000-0000-0000-000000000091') AS bal,
  (SELECT -sum(p.amount) FROM posting p JOIN journal_transaction t ON t.id = p.transaction_id
    WHERE p.account_id = '20000000-0000-0000-0000-000000000091' AND p.amount < 0 AND t.type IN ('TOPUP','TOPUP_CASH')) AS mtot;
SELECT is(((SELECT h FROM hr))::text, ((SELECT least(greatest(150000 - bal, 0), greatest(200000 - mtot, 0)) FROM hr))::text,$Q$marge de recharge : minimum du plafond de solde et du plafond mensuel restants$Q$);
SELECT lives_ok($Q$DO $D$ DECLARE h bigint := (SELECT h FROM hr); l jsonb; BEGIN
  l := jsonb_build_array(jsonb_build_object('account_id','20000000-0000-0000-0000-000000000094','amount',100000),
                         jsonb_build_object('account_id','20000000-0000-0000-0000-000000000095','amount',-(100000 - h)));
  IF h > 0 THEN l := l || jsonb_build_array(jsonb_build_object('account_id','20000000-0000-0000-0000-000000000091','amount',-h)); END IF;
  PERFORM post_transaction('10000000-0000-0000-0000-000000000002','TOPUP_CASH','cashover:1',now(),'OFFLINE_SYNC', l);
END $D$$Q$, $Q$recharge espèces au-delà du plafond : portefeuille crédité de la marge, le reste dû au client$Q$);
SELECT is(((SELECT -sum(amount) FROM posting WHERE account_id = '20000000-0000-0000-0000-000000000095'))::text, ((SELECT 100000 - h FROM hr))::text,$Q$espèces dues au client = recharge moins la marge$Q$);
