SELECT is((wallet_kyc_level('30000000-0000-0000-0000-000000000092'))::text, ('VERIFIED')::text,$Q$identification valide du client : portefeuille identifié$Q$);
SELECT is((wallet_kyc_level('30000000-0000-0000-0000-000000000092', current_date + 400))::text, ('NONE')::text,$Q$pièce expirée : le niveau retombe sans tâche planifiée$Q$);
