SELECT throws_like($Q$INSERT INTO kyc_verification (operator_id, customer_id, agent_id, id_type, id_country, id_last4, id_expires_on) VALUES ('00000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-0000000000c1','90000000-0000-0000-0000-000000000001','PASSPORT','SN','A1234567', current_date + 30)$Q$, $Q$%id_last4%$Q$, $Q$numéro complet de la pièce refusé (4 derniers caractères seulement)$Q$);
