SELECT is(((SELECT prev_seal_hash FROM ledger_seal WHERE ledger_id = '10000000-0000-0000-0000-000000000001' AND seal_no = 2))::text, ((SELECT seal_hash FROM ledger_seal WHERE ledger_id = '10000000-0000-0000-0000-000000000001' AND seal_no = 1))::text,$Q$scellements chaînés$Q$);
SELECT is(((SELECT bool_and(ok) FROM verify_ledger_seals('10000000-0000-0000-0000-000000000001')))::text, (true)::text,$Q$vérification : aucun écart$Q$);
SELECT throws_like($Q$UPDATE ledger_seal SET postings = 1 WHERE ledger_id = '10000000-0000-0000-0000-000000000001' AND seal_no = 1$Q$, $Q$%ajout seul%$Q$, $Q$scellement non modifiable$Q$);
SELECT lives_ok($Q$UPDATE ledger_seal SET external_ref = 's3://seals/10000000-0000-0000-0000-000000000001/1' WHERE ledger_id = '10000000-0000-0000-0000-000000000001' AND seal_no = 1$Q$, $Q$référence de la copie externe renseignée$Q$);
SELECT throws_like($Q$UPDATE ledger_seal SET external_ref = 's3://autre' WHERE ledger_id = '10000000-0000-0000-0000-000000000001' AND seal_no = 1$Q$, $Q$%ajout seul%$Q$, $Q$référence externe renseignée une seule fois$Q$);
SET ROLE app_test; SET app.operator_id = '00000000-0000-0000-0000-000000000009';
SELECT throws_like($Q$SELECT seal_ledger('10000000-0000-0000-0000-000000000001', interval '0')$Q$, $Q$Objet introuvable$Q$, $Q$autre prestataire : scellement refusé$Q$);
RESET ROLE; SET app.operator_id = '00000000-0000-0000-0000-000000000002';
SET CONSTRAINTS ALL IMMEDIATE; ALTER TABLE posting DISABLE TRIGGER posting_immutable; UPDATE posting SET amount = amount + 1 WHERE id = (SELECT min(id) FROM posting WHERE ledger_id = '10000000-0000-0000-0000-000000000001');
SELECT is(((SELECT string_agg(seal_no || ':' || ok, ',' ORDER BY seal_no) FROM verify_ledger_seals('10000000-0000-0000-0000-000000000001')))::text, ('1:false,2:true')::text,$Q$altération d'un montant scellé : détectée dans le bon scellement$Q$);
DELETE FROM posting WHERE id = (SELECT max(id) FROM posting WHERE ledger_id = '10000000-0000-0000-0000-000000000001'); ALTER TABLE posting ENABLE TRIGGER posting_immutable;
SELECT is(((SELECT string_agg(seal_no || ':' || ok, ',' ORDER BY seal_no) FROM verify_ledger_seals('10000000-0000-0000-0000-000000000001')))::text, ('1:false,2:false')::text,$Q$suppression d'une ligne scellée : détectée$Q$);
SELECT seal_ledger('10000000-0000-0000-0000-000000000002', interval '0'); SET CONSTRAINTS ALL IMMEDIATE; ALTER TABLE journal_transaction DISABLE TRIGGER USER; UPDATE journal_transaction SET created_by = gen_random_uuid() WHERE id = (SELECT min(id::text)::uuid FROM journal_transaction WHERE ledger_id = '10000000-0000-0000-0000-000000000002'); ALTER TABLE journal_transaction ENABLE TRIGGER USER;
SELECT is(((SELECT bool_and(ok) FROM verify_ledger_seals('10000000-0000-0000-0000-000000000002')))::text, (false)::text,$Q$auteur d'une écriture scellée modifié : détecté (revue 2)$Q$);
SELECT * FROM finish();
ROLLBACK;
